    async def release_a_company(
        self,
        id: str,
        *,
        idempotency_key: str,
        reason: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CompanyReleaseReceipt:
        """
        End all of this partner's access to a managed company. The company keeps its submitted cases, users, portal access and any credentials of its own. Orders this partner created on the company's behalf and never submitted are deleted; submitted orders and the company's own drafts survive. The company's `external_reference` is cleared so the same reference can onboard a fresh company later; the record itself stays attributed to the partner for history. Emits `company.access.revoked` with `reason: "partner_released"`. Requires an `Idempotency-Key` header and the `partner:companies:write` scope. Returns only an id and `case_access: unavailable` receipt. The same key replays this receipt; a new key after disconnection returns 404.

        Parameters
        ----------
        id : str
            UUID of the managed company in this request.

        idempotency_key : str
            Required client-supplied key scoped to the Partner owner, method, operation and path. An exact retry replays the original response while it is retained, including after credential rotation or replacement. Current permissions are required.

        reason : typing.Optional[str]
            Optional single-line note for the partner's own records, up to 5000 characters. It is not stored on the company and never appears in webhook payloads.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CompanyReleaseReceipt


        Examples
        --------
        import asyncio

        from paywise import AsyncPaywise

        client = AsyncPaywise(
            on_behalf_of_company="YOUR_ON_BEHALF_OF_COMPANY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.partner.companies.release_a_company(
                id="id",
                idempotency_key="Idempotency-Key",
                reason="Client ended the partner engagement.",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.release_a_company(
            id, idempotency_key=idempotency_key, reason=reason, request_options=request_options
        )
        return _response.data
